48	pub fn batch(
49	    rx: Receiver<WorkerResult>,
50	    cmd: &CommandTemplate,
51	    show_filesystem_errors: bool,
52	    buffer_output: bool,
53	) -> ExitCode {
54	    let paths = rx.iter().filter_map(|value| match value {
55	        WorkerResult::Entry(val) => Some(val),
56	        WorkerResult::Error(err) => {
57	            if show_filesystem_errors {
58	                print_error(err.to_string());
59	            }
60	            None
61	        }
62	    });
63	    cmd.generate_and_execute_batch(paths, buffer_output)
64	}
