162	    pub fn generate_and_execute_batch<I>(&self, paths: I, buffer_output: bool) -> ExitCode
163	    where
164	        I: Iterator<Item = PathBuf>,
165	    {
166	        let mut cmd = Command::new(self.args[0].generate("", None));
167	        cmd.stdin(Stdio::inherit());
168	        cmd.stdout(Stdio::inherit());
169	        cmd.stderr(Stdio::inherit());
170	
171	        let mut paths: Vec<_> = paths.collect();
172	        let mut has_path = false;
173	
174	        for arg in &self.args[1..] {
175	            if arg.has_tokens() {
176	                paths.sort();
177	
178	                // A single `Tokens` is expected
179	                // So we can directly consume the iterator once and for all
180	                for path in &mut paths {
181	                    cmd.arg(arg.generate(strip_current_dir(path), self.path_separator.as_deref()));
182	                    has_path = true;
183	                }
184	            } else {
185	                cmd.arg(arg.generate("", None));
186	            }
187	        }
188	
189	        if has_path {
190	            execute_command(cmd, &Mutex::new(()), buffer_output)
191	        } else {
192	            ExitCode::Success
193	        }
194	    }
195	}
